/** No provider tokens, third-party scripts, telemetry or automatic model calls in this browser. */
const $=id=>document.getElementById(id);
const embedded=Boolean($('app'));
let hostOptions=null, startup=null;
const ownsEvent=e=>!embedded||Boolean(e.target.closest?.('#connectedHost, #connectedOverlays'));
const href=route=>embedded?'#'+(route==='connections'?route:'connected-'+route):'#'+route;
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='fr';try{lang=new URLSearchParams(location.search).get('lang')||sessionStorage.getItem('essentiel-connected-language')||'fr';}catch{}if(!['fr','en'].includes(lang))lang='fr';
let data={vault:{locked:false,persistent:false},providers:[],snapshots:{},diagnostics:{},actions:[],selections:{}},config={configured:false,draft:{configured:false}};
const ui={route:location.hash.slice(1)||'inbox',busy:false,search:'',onlyUnread:false,message:null,triage:null,files:null,slots:null,automatic:false,lastError:'',theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'};
const L=(fr,en)=>lang==='fr'?fr:en;
const P=p=>p==='google'?'Google':'Microsoft';
const draftReady=()=>Boolean(config.draft?.configured);
const engineName=()=>{const d=config.draft||{};return ({claude:'Claude Code',codex:'Codex',openai:d.local?L('LLM local','Local LLM'):L('API compatible OpenAI','OpenAI-compatible API')})[d.engine]||L('un moteur de rédaction','a drafting engine');};
const engineLabel=(g=config.draft)=>engineName()+(g?.model?' · '+g.model:'');
const provider=p=>data.providers.find(x=>x.id===p);
const connected=()=>data.providers.filter(x=>x.connected);
const rows=key=>Object.values(data.snapshots).flatMap(s=>s[key]||[]);
const attr=obj=>Object.entries(obj||{}).map(([k,v])=>` data-${k}="${escape(v)}"`).join('');
const button=(label,action,extra={},cls='',disabled=false)=>`<button type="button" class="btn ${cls}" data-action="${action}"${attr(extra)} ${disabled?'disabled':''}>${escape(label)}</button>`;
const pill=(label,cls='')=>`<span class="pill ${cls}">${escape(label)}</span>`;
const link=(url,label,cls='btn small')=>url?`<a href="${escape(url)}" class="${cls}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`:'';
const input=(name,label,value='',type='text',extra='')=>`<label>${escape(label)}<input name="${name}" value="${escape(value)}" type="${type}" ${extra}></label>`;
const textarea=(name,label,value='',extra='')=>`<label>${escape(label)}<textarea name="${name}" ${extra}>${escape(value)}</textarea></label>`;
const select=(name,label,items,value,extra='')=>`<label>${escape(label)}<select name="${name}" ${extra}>${items.map(([id,title])=>`<option value="${escape(id)}" ${id===value?'selected':''}>${escape(title)}</option>`).join('')}</select></label>`;
const fmt=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat(lang==='fr'?'fr-CA':'en-CA',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const localInput=date=>{const d=new Date(date);return new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const isoInput=v=>{const d=new Date(v);if(!v||!Number.isFinite(+d))throw new Error(L('Date et heure nécessaires.','Date and time required.'));return d.toISOString();};
const tomorrow=()=>{const d=new Date();d.setDate(d.getDate()+1);d.setHours(9,0,0,0);return d;};
const feat=f=>({mail:L('Lire les courriels','Read mail'),calendar:L('Lire les calendriers','Read calendars'),tasks:L('Lire les tâches','Read tasks'),files:L('Chercher des documents','Search documents'),drafts:L('Créer des brouillons','Create drafts'),calendar_write:L('Créer des créneaux personnels','Create personal time blocks'),tasks_write:L('Créer et terminer des tâches','Create and complete tasks')})[f]||f;
const kind=k=>({draft:L('Brouillon dans la messagerie','Draft in the mailbox'),event:L('Créneau personnel dans le calendrier','Personal calendar time block'),task:L('Tâche dans votre outil','Task in your tool'),complete_task:L('Terminer la tâche','Complete task')})[k]||k;
const state=s=>({pending:L('À approuver','Awaiting approval'),executing:L('Exécution en cours','Executing'),verified:L('Objet vérifié dans le service','Object verified in the service'),created_unverified:L('ID reçu · relecture non confirmée','ID received · read-back unconfirmed'),uncertain:L('Résultat incertain · vérifier le service','Uncertain outcome · check the service'),blocked:L('Bloquée avant écriture','Blocked before write'),rejected:L('Refusée par le service','Rejected by the service'),cancelled:L('Proposition annulée','Proposal cancelled')})[s]||s;
const paths={inbox:'M3 5h18v14H3V5Zm0 1 9 7 9-7',calendar:'M4 5h16v16H4V5Zm4-3v6m8-6v6M4 10h16',tasks:'m3 6 2 2 4-4m3 2h9M3 13h6m3 0h9M3 20h6m3 0h9',files:'M3 7h7l2-3h9v16H3V7Z',actions:'m4 12 5 5L20 5M3 21h18',connections:'M8 4v6m8-6v6M5 10h14v3a7 7 0 0 1-14 0v-3Zm7 10v3'};
const icon=k=>`<svg class="glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.actions}"/></svg>`;
let toastTimer;
function toast(message){$('notice').textContent=message;$('notice').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').hidden=true,8000);}
function error(e){if(e.diagnostic){const markup=diagnosticCard(e.diagnostic.provider,{service:e.diagnostic.service,code:e.code,diagnostic:e.diagnostic},true);if($('dialog').open&&$('formError'))$('formError').innerHTML=markup;else show(L('Accès au service à corriger','Service access needs attention'),markup);return;}const msg=e.message||String(e);if($('dialog').open&&$('formError'))$('formError').textContent=msg;else toast(msg);}
async function api(route,body,timeoutMs=0){const url=route.startsWith('/api/')?route:'/api/connected/'+route;let response;try{response=await fetch(url,{method:body===undefined?'GET':'POST',headers:{'X-Essentiel-Request':'1',...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)}),...(timeoutMs?{signal:AbortSignal.timeout(timeoutMs)}:{})});}catch(e){if(e?.name==='TimeoutError')throw new Error(L('Délai local dépassé. Aucun résultat substitué.','Local time limit exceeded. No result substituted.'));throw e;}const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error||response.statusText),{code:result.code,diagnostic:result.diagnostic});return result;}
async function reload(){data=await api('status');render();}
async function work(fn){if(ui.busy)return;ui.busy=true;document.body.classList.add('busy');try{await fn();}catch(e){error(e);}finally{ui.busy=false;document.body.classList.remove('busy');}}
function show(title,body){$('dialogBody').innerHTML=`<div class="dialog-heading"><h2 id="dialogTitle">${escape(title)}</h2>${button(L('Fermer','Close'),'close',{},'small')}</div><div id="formError" class="error" role="alert"></div>${body}`;if(!$('dialog').open)$('dialog').showModal();}
function footer(label=L('Continuer','Continue')){return `<div class="dialog-footer">${button(L('Annuler','Cancel'),'close')}<button type="submit" class="btn primary">${escape(label)}</button></div>`;}
function empty(title,description){return `<div class="card empty"><h2>${escape(title)}</h2><p>${escape(description)}</p><a class="btn primary" href="#connections">${L('Connexions','Connections')}</a></div>`;}
function heading(title,description,actions=''){return `<div class="heading"><div><div class="eyebrow">ESSENTIEL / ${escape(L('VOS OUTILS, UNE SUITE D’ACTIONS','YOUR TOOLS, ONE ACTION FLOW'))}</div><h1>${escape(title)}</h1><p>${escape(description)}</p></div><div class="actions">${actions}</div></div>`;}
function diagnosticCopy(d={}){
  const api=d.api||L('Ce service','This service');
  const table={
    api_disabled:[L(api+' non activée dans le projet Google.',api+' is not enabled in the Google project.'),L('Ouvrez la fiche de cette API, sélectionnez le projet du client OAuth utilisé par Essentiel, puis activez-la. Réessayez ensuite la lecture.','Open this API, select the project of the OAuth client used by Essentiel, enable it, then retry the read.')],
    insufficient_scopes:[L('Autorisation insuffisante pour cette opération.','Insufficient authorization for this operation.'),L('Dans Connexions, cochez le service requis et utilisez « Réautoriser / étendre les droits ». Accordez le droit correspondant chez Google ou Microsoft.','In Connections, select the required service and use “Reauthorize / extend permissions”. Grant its permission at Google or Microsoft.')],
    admin_policy:[L('Accès bloqué par une règle de l’organisation.','Access blocked by an organization policy.'),L('L’administrateur du compte doit autoriser cette application et le service. Un changement de localhost ne lève pas cette restriction.','The account administrator must authorize this app and service. Changing localhost does not remove this restriction.')],
    quota:[L('Limite de requêtes ou quota atteint.','Request limit or quota reached.'),L('Interrompez les relances répétées. Vérifiez les quotas du projet et réessayez après le délai du fournisseur. Aucune écriture n’est répétée automatiquement.','Stop repeated retries. Check project quotas and retry after the provider delay. No write is retried automatically.')],
    reauthorize:[L('La connexion doit être renouvelée.','The connection must be renewed.'),L('Réautorisez ce compte depuis Connexions.','Reauthorize this account from Connections.')],
    client_configuration:[L('Le client OAuth a été refusé.','The OAuth client was rejected.'),L('Vérifiez le client configuré dans .env ou le JSON OAuth, puis redémarrez le serveur.','Check the client configured in .env or the OAuth JSON, then restart the server.')],
    forbidden:[L('Opération refusée, cause précise non identifiée.','Operation refused; the exact cause is not identified.'),L('Vérifiez l’activation de l’API, les droits accordés et les règles du compte. Le seul code 403 ne permet pas de choisir une cause.','Check API activation, granted permissions and account policies. HTTP 403 alone does not identify one cause.')],
    temporary:[L('Erreur temporaire du fournisseur.','Temporary provider error.'),L('Réessayez la lecture ultérieurement. Ne répétez pas une écriture dont le résultat est incertain.','Retry the read later. Do not repeat a write with an uncertain outcome.')],
    not_found:[L('Ressource introuvable ou inaccessible.','Resource missing or inaccessible.'),L('Vérifiez le compte et la ressource choisis.','Check the selected account and resource.')]
  };
  return table[d.category]||[L('Échec de l’appel au fournisseur.','Provider request failed.'),L('Consultez le code du diagnostic et vérifiez la configuration.','Inspect the diagnostic code and check configuration.')];
}
function diagnosticCard(p,e,compact=false){
  const d=e.diagnostic||{},copy=diagnosticCopy(d),service=e.service||d.service;
  return `<section class="banner warn diagnostic" role="status"><strong>${escape(P(p)+' · '+feat(service)+' — '+copy[0])}</strong><p>${escape(copy[1])}</p>${d.project?`<p>${L('Projet indiqué par Google : ','Project reported by Google: ')}<code>${escape(d.project)}</code></p>`:''}<div class="actions">${d.consoleUrl?link(d.consoleUrl,L('Ouvrir cette API dans Google Cloud','Open this API in Google Cloud')):''}${button(L('Tester les accès','Test access'),'diagnostics',{provider:p},'small')}<a class="btn small" href="${href('connections')}">${L('Gérer les autorisations','Manage permissions')}</a></div><details><summary>${L('Diagnostic technique sans jetons','Technical diagnostic without tokens')}</summary><pre class="code">${escape(JSON.stringify({service,code:e.code||'',...d},null,2))}</pre></details>${!compact?`<p class="fine">${L('Les éléments éventuellement conservés sont ceux d’une lecture précédente. Un échec ne signifie pas une boîte vide.','Any retained items come from an earlier read. Failure does not mean an empty inbox.')}</p>`:''}</section>`;
}
function dataWarnings(){return connected().flatMap(p=>(data.snapshots[p.id]?.errors||[]).map(e=>diagnosticCard(p.id,e))).join('');}
function serviceMetric(service,key){
  const authorized=connected().filter(p=>p.capabilities[service]);
  if(!authorized.length)return '—';
  const available=authorized.filter(p=>data.snapshots[p.id]?.[service+'UpdatedAt']);
  return available.length?String(rows(key).length):'—';
}
function serviceSummary(p){
  const report=data.diagnostics?.[p.id],snap=data.snapshots[p.id];
  const checks=['mail','calendar','tasks','files'].map(service=>{
    const tested=report?.checks?.find(c=>c.service===service),error=snap?.errors?.find(e=>e.service===service);
    if(!p.capabilities[service])return {service,status:'not_granted'};
    if(tested && (service==='files'||!snap?.attemptedAt||report.checkedAt>=snap.attemptedAt))return tested;
    return {service,status:error?'error':snap?.[service+'UpdatedAt']?'ok':'untested',...(error||{})};
  });
  return `<div class="service-status">${checks.map(c=>`<div class="service-status-row"><span>${escape(feat(c.service))}</span>${pill(c.status==='ok'?L('Lecture réussie','Read succeeded'):c.status==='error'?L('Lecture refusée / en erreur','Read refused / failed'):c.status==='not_granted'?L('Non autorisé','Not authorized'):L('Non testé','Not tested'),c.status==='ok'?'good':c.status==='error'?'bad':'')}</div>`).join('')}</div><p class="fine">${report?L('Dernier test : ','Last test: ')+escape(fmt(report.checkedAt)):L('État de la dernière synchronisation.','Status of the last synchronization.')} ${L('Ces contrôles testent la lecture, jamais une écriture.','These checks test reads, never writes.')}</p><div class="actions">${button(L('Tester les accès','Test access'),'diagnostics',{provider:p.id},'small')}${button(L('Exporter le diagnostic','Export diagnostic'),'export-diagnostic',{provider:p.id},'small',!report)}</div>${checks.filter(c=>c.status==='error').map(e=>diagnosticCard(p.id,e,true)).join('')}`;
}
function render(){
  if(!embedded){document.documentElement.lang=lang;document.documentElement.dataset.theme=ui.theme;}
  if(embedded&&!$('connectedHost'))return;
  const labels={inbox:L('À traiter','Inbox to action'),calendar:L('Temps disponible','Available time'),tasks:L('Tâches réelles','Connected tasks'),files:L('Documents','Documents'),actions:L('Actions et preuves','Actions and receipts'),connections:L('Connexions','Connections')};
  if(!labels[ui.route])ui.route='inbox';
  const content=data.vault.locked?lockedView():({inbox:inboxView,calendar:calendarView,tasks:tasksView,files:filesView,actions:actionsView,connections:connectionsView})[ui.route]();
  if(embedded){
    let markup=`<div class="connected-toolbar"><span>${escape(data.vault.locked?L('Coffre connecté verrouillé','Connected vault locked'):data.vault.persistent?L('Comptes · coffre local chiffré','Accounts · encrypted local vault'):L('Comptes · session serveur en mémoire','Accounts · server memory session'))}</span>${button(data.vault.locked?L('Déverrouiller','Unlock'):data.vault.persistent?L('Verrouiller','Lock'):L('Conserver les connexions chiffrées','Keep connections encrypted'),'vault',{},'small')}</div>${ui.lastError?`<div class="banner bad">${escape(ui.lastError)}</div>`:''}${content}`;
    markup=markup.replace(/href="#(inbox|calendar|tasks|files|actions|connections)"/g,(_,route)=>`href="${href(route)}"`).replace(/href="\/workspace\?lang=(fr|en)"/g,'href="#today"');
    $('connectedHost').innerHTML=markup;return;
  }
  $('root').innerHTML=`<div class="shell"><aside class="rail"><a href="#inbox" class="brand">essentiel<span>.</span></a><div class="caption">${L('Moins à porter. Plus de concret.','Less to carry. More done.')}</div><nav aria-label="${L('Navigation principale','Main navigation')}">${Object.entries(labels).map(([id,title])=>`<a href="#${id}" class="nav ${id===ui.route?'active':''}" ${id===ui.route?'aria-current="page"':''}>${icon(id)}${escape(title)}</a>`).join('')}</nav><div class="rail-bottom"><a class="nav" href="/workspace?lang=${lang}">${icon('tasks')}${L('Tous les outils locaux','All local tools')}</a><p class="rail-note">${L('Application locale · 0.3.2\nAucun paiement. Aucun courriel envoyé automatiquement.','Local application · 0.3.2\nNo payments. No automatically sent mail.')}</p></div></aside><div class="main-wrap"><header class="topbar"><span class="status-label">${escape(data.vault.locked?L('Coffre verrouillé','Vault locked'):data.vault.persistent?L('Coffre local chiffré','Encrypted local vault'):L('Session en mémoire · non conservée après arrêt','Memory session · not retained after shutdown'))}</span><div class="right">${button(lang==='fr'?'EN':'FR','language',{},'small')}${button(ui.theme==='light'?L('Sombre','Dark'):L('Clair','Light'),'theme',{},'small')}${button(data.vault.locked?L('Déverrouiller','Unlock'):data.vault.persistent?L('Verrouiller','Lock'):L('Conserver chiffré','Save encrypted'),'vault',{},'small')}</div></header><main id="main">${ui.lastError?`<div class="banner bad">${escape(ui.lastError)}</div>`:''}${content}</main></div></div>`;
}
function lockedView(){return heading(L('Votre espace est verrouillé.','Your workspace is locked.'),L('Les jetons de connexion, sources et actions restent dans le fichier chiffré.','Connection tokens, sources and actions remain inside the encrypted file.'))+`<div class="card empty"><h2>${L('Déverrouiller sur cet appareil','Unlock on this device')}</h2><p>${L('La phrase secrète ne quitte pas ce serveur local. Elle n’est pas récupérable.','The passphrase does not leave this local server. It cannot be recovered.')}</p>${button(L('Déverrouiller','Unlock'),'vault',{},'primary')}</div>`;}
function onboarding(){return `<div class="banner">${L('Pas de données de démonstration. Rien n’est connecté tant que vous ne l’avez pas autorisé.','No demonstration data. Nothing is connected until you authorize it.')}</div><div class="cards"><section class="card"><div class="step-number">1</div><h2>${L('Partir de ce qui existe déjà','Start with what already exists')}</h2><p class="fine">${L('Gmail ou Outlook pour les demandes. Google Calendar ou Outlook pour le temps. Google Tasks ou Microsoft To Do pour le suivi.','Gmail or Outlook for requests. Google Calendar or Outlook for time. Google Tasks or Microsoft To Do for follow-through.')}</p><a href="#connections" class="btn primary">${L('Choisir mes outils','Choose my tools')}</a></section><section class="card"><div class="step-number">2</div><h2>${L('Terminer une opération, pas remplir un tableau','Complete an operation, not another dashboard')}</h2><p class="fine">${L('Ouvrir le message original, préparer un brouillon dans la messagerie, réserver un créneau ou créer une tâche reliée à sa source. Vous validez le contenu avant chaque écriture.','Open the original message, prepare a draft in your mailbox, reserve a time block or create a source-linked task. Approve the exact content before every write.')}</p>${pill(L('Source → aperçu → approbation → relecture','Source → preview → approval → read-back'),'good')}</section></div>`;}
function inboxView(){
  const messages=rows('messages').filter(m=>(!ui.onlyUnread||m.unread)&&(!ui.search||[m.title,m.from,m.text].join(' ').toLocaleLowerCase().includes(ui.search.toLocaleLowerCase()))).sort((a,b)=>b.receivedAt.localeCompare(a.receivedAt));
  let html=heading(L('Ce qui demande votre attention.','What needs your attention.'),L('Vos courriels deviennent le point de départ d’actions dans vos outils. Aucun classement du modèle ne vaut autorisation.','Your mail becomes the starting point for actions in your tools. Model classification is never authorization.'),button(L('Synchroniser','Sync'),'sync-all',{},'primary',!connected().length));
  if(!connected().length)return html+onboarding();
  html+=dataWarnings()+`<div class="metrics"><div class="metric"><strong>${serviceMetric('mail','messages')}</strong><span>${L('courriels chargés, périmètre limité','loaded messages, limited scope')}</span></div><div class="metric"><strong>${serviceMetric('tasks','tasks')}</strong><span>${L('tâches ouvertes chargées','loaded open tasks')}</span></div><div class="metric"><strong>${data.actions.filter(a=>a.status==='verified').length}</strong><span>${L('opérations vérifiées, journal local','verified operations, local journal')}</span></div></div><form data-form="inbox-filter" class="searchbar"><input name="q" aria-label="${L('Rechercher dans les sources chargées','Search loaded sources')}" placeholder="${L('Rechercher un courriel chargé…','Search loaded messages…')}" value="${escape(ui.search)}"><label class="check"><input type="checkbox" name="unread" ${ui.onlyUnread?'checked':''}>${L('Non lus seulement','Unread only')}</label><button class="btn" type="submit">${L('Filtrer','Filter')}</button></form><p class="fine">${L('Les 30 courriels les plus récents de chaque boîte de réception autorisée. Ce n’est pas une analyse exhaustive de votre compte.','The newest 30 messages from each authorized inbox. This is not an exhaustive account analysis.')}</p>`;
  if(!messages.length && connected().some(p=>data.snapshots[p.id]?.errors?.some(e=>e.service==='mail')))
    return html+empty(L('Impossible de charger les courriels.','Mail could not be loaded.'),L('La lecture a échoué. Corrigez le diagnostic indiqué plus haut, puis synchronisez. Ce n’est pas une boîte vide.','The read failed. Resolve the diagnostic above, then sync. This is not an empty inbox.'));
  if(!messages.length)return html+empty(L('Aucun courriel chargé pour ce filtre.','No loaded messages match this filter.'),L('Synchronisez une messagerie autorisée. Une permission absente ou une erreur n’est pas traitée comme une boîte vide.','Synchronize an authorized mailbox. A missing permission or error is not treated as an empty inbox.'));
  return html+`<section class="card" aria-label="${L('Messages chargés','Loaded messages')}">${messages.map(m=>`<article class="row"><div class="row-main"><div class="meta">${pill(P(m.provider))}${m.unread?pill(L('Non lu','Unread'),'good'):''}<span>${escape(m.from)}</span></div><h3><button type="button" class="row-title" data-action="message"${attr({provider:m.provider,id:m.id})}>${escape(m.title||L('(Sans objet)','(No subject)'))}</button></h3><p>${escape(m.text.slice(0,210))}${m.text.length>210?'…':''}</p><div class="actions">${button(L('Ouvrir et agir','Open and act'),'message',{provider:m.provider,id:m.id},'small')}${link(m.url,L('Original','Original'))}</div></div><div class="row-side">${escape(fmt(m.receivedAt))}</div></article>`).join('')}</section>`;
}
function calendarView(){const events=rows('events').sort((a,b)=>a.start.localeCompare(b.start));return heading(L('Trouver du temps réellement libre.','Find time that is actually free.'),L('Croiser les calendriers sélectionnés, puis revérifier juste avant de créer un créneau personnel. Cela ne confirme pas un rendez-vous avec un tiers.','Cross-check selected calendars, then check again before creating a personal time block. This does not book or confirm an appointment with another party.'),button(L('Chercher un créneau','Find a time slot'),'slot-form',{},'primary',!connected().some(p=>p.capabilities.calendar)))+dataWarnings()+`<p class="fine">${L('Couverture : calendriers choisis dans Connexions. Les calendriers non connectés et la disponibilité des autres personnes sont inconnus. Fuseau du navigateur : ','Coverage: calendars selected in Connections. Unconnected calendars and other people’s availability are unknown. Browser time zone: ')}${escape(Intl.DateTimeFormat().resolvedOptions().timeZone)}</p><div class="actions">${button(L('Créer un créneau personnel','Create a personal time block'),'compose',{kind:'event'},'',!connected().some(p=>p.capabilities.calendar_write))}${button(L('Synchroniser','Sync'),'sync-all',{},'',!connected().length)}</div><div class="spacer"></div>${events.length?`<section class="card">${events.map(e=>`<article class="row"><div class="row-main"><div class="meta">${pill(P(e.provider))}${pill(e.calendarName)}${e.allDay?pill(L('Journée entière','All day')):''}${!e.busy?pill(L('Ne bloque pas le temps','Does not block time')):''}</div><h3>${escape(e.title||L('(Événement privé)','(Private event)'))}</h3><p>${escape(fmt(e.start))} — ${escape(fmt(e.end))}</p>${link(e.url,L('Voir dans le calendrier','Open in calendar'))}</div></article>`).join('')}</section>`:empty(L('Aucun événement chargé.','No loaded events.'),L('Un agenda sans données chargées ne prouve pas que vous êtes disponible.','An agenda without loaded data is not proof of availability.'))}`;}
function tasksView(){const tasks=rows('tasks');return heading(L('Le suivi reste dans vos outils.','Follow-through stays in your tools.'),L('Les tâches sont lues, créées et terminées dans Google Tasks ou Microsoft To Do. Une tâche créée n’est pas encore un problème résolu.','Tasks are read, created and completed in Google Tasks or Microsoft To Do. Creating a task is not the same as solving the underlying problem.'),button(L('Créer une tâche','Create a task'),'compose',{kind:'task'},'primary',!connected().some(p=>p.capabilities.tasks_write)))+dataWarnings()+`<p class="fine">${L('Une liste choisie par fournisseur. Changez la sélection dans Connexions. Les échéances saisies ici sont des dates, pas des garanties de notification.','One selected list per provider. Change the selection in Connections. Due dates entered here are calendar dates, not notification guarantees.')}</p>${tasks.length?`<section class="card">${tasks.map(t=>`<article class="row"><div class="row-main"><div class="meta">${pill(P(t.provider))}${pill(t.listName)}</div><h3>${escape(t.title)}</h3><p>${escape(t.notes.slice(0,180))}</p><div class="actions">${button(L('Marquer terminée','Mark complete'),'complete-task',{provider:t.provider,id:t.id,list:t.listId},'small',!provider(t.provider).capabilities.tasks_write)}${link(t.url,L('Ouvrir l’outil','Open tool'))}</div></div><div class="row-side">${escape(t.due||L('Sans date','No date'))}</div></article>`).join('')}</section>`:empty(L('Aucune tâche ouverte chargée.','No loaded open tasks.'),L('Autorisez la lecture des tâches et synchronisez la liste choisie.','Authorize task reading and synchronize the selected list.'))}`;}
function filesView(){const active=connected().filter(p=>p.capabilities.files);return heading(L('Retrouver le document au bon endroit.','Find the document where it lives.'),L('Recherche distante dans Google Drive ou OneDrive. L’application affiche les noms et liens ; elle ne télécharge ni n’analyse le contenu des documents.','Remote search in Google Drive or OneDrive. The application shows names and links; it does not download or analyze document contents.'))+`<form data-form="file-search" class="card"><div class="two">${input('query',L('Nom, mot ou fragment à rechercher','Name, word or fragment to search'),'','text','required maxlength="150"')}${select('provider',L('Compte','Account'),active.map(p=>[p.id,`${P(p.id)} · ${p.email}`]),active[0]?.id)}</div><button class="btn primary" type="submit" ${!active.length?'disabled':''}>${L('Rechercher dans le service','Search the service')}</button><p class="fine">${L('Google : nom de fichier. OneDrive : recherche du service, qui peut aussi indexer le contenu. Maximum 50 résultats affichés ; le corpus n’est pas copié.','Google: file-name search. OneDrive: service search, which may also index contents. Up to 50 results shown; the corpus is not copied.')}</p></form><div class="spacer"></div>${!active.length?empty(L('Aucun espace documentaire autorisé.','No document service authorized.'),L('L’autorisation de recherche documentaire est distincte des courriels et calendriers.','Document-search permission is separate from mail and calendar access.')):ui.files?`<section class="card"><div class="section-head"><h2>${L('Résultats','Results')}</h2>${pill(ui.files.partial?L('Résultats partiels','Partial results'):L('Page reçue','Page received'),ui.files.partial?'warn':'')}</div>${ui.files.items.length?ui.files.items.map(f=>`<article class="row"><div class="row-main"><div class="meta">${pill(P(f.provider))}<span>${escape(f.type)}</span></div><h3>${escape(f.title)}</h3><p>${escape(fmt(f.modifiedAt))}</p>${link(f.url,L('Ouvrir le document original','Open original document'))}</div></article>`).join(''):`<p class="fine">${L('Aucun résultat retourné pour cette recherche.','No results returned for this search.')}</p>`}</section>`:''}`;}
function actionsView(){return heading(L('Ce qui a vraiment été fait.','What actually happened.'),L('Chaque écriture a son aperçu, son accord explicite et son résultat. Une relecture réussie prouve l’existence de l’objet, pas la réussite de votre objectif.','Every write has a preview, explicit approval and a result. A successful read-back proves the object exists, not that your goal has been achieved.'),button(L('Exporter le journal','Export journal'),'export',{},'',!data.actions.length))+`<div class="banner warn">${L('Un résultat incertain ne doit pas être relancé à l’aveugle. Vérifiez le service original. Les reçus locaux sont des traces techniques, pas des attestations infalsifiables.','An uncertain result must not be blindly retried. Check the original service. Local receipts are technical records, not tamper-proof attestations.')}</div>${data.actions.length?`<section class="card">${data.actions.map(a=>`<article class="row"><div class="row-main"><div class="meta">${pill(P(a.provider))}${pill(state(a.status),a.status==='verified'?'good':['uncertain','created_unverified'].includes(a.status)?'warn':'')}</div><h3>${escape(a.payload.title||a.payload.subject||kind(a.kind))}</h3><p>${escape(kind(a.kind))} · ${escape(a.account)}</p><div class="actions">${button(L('Détails et preuve','Details and receipt'),'action-details',{id:a.id},'small')}${a.status==='pending'?button(L('Revoir avant exécution','Review before execution'),'review-action',{id:a.id},'small'):''}${a.receipt?.url?link(a.receipt.url,L('Vérifier dans le service','Check the service')):''}</div></div><div class="row-side">${escape(fmt(a.createdAt))}</div></article>`).join('')}</section>`:empty(L('Aucune opération enregistrée.','No recorded operations.'),L('Une connexion ou une synchronisation n’est pas comptée comme une action accomplie.','Connecting or synchronizing is not counted as a completed action.'))}`;}
function connectionsView(){
  const cards=data.providers.map(p=>{const caps=p.capabilities,s=data.snapshots[p.id];return `<section class="card"><div class="provider-head"><div class="provider-logo">${p.id==='google'?'G':'M'}</div><div><h2>${P(p.id)}</h2><p>${escape(p.email||L('Aucun compte connecté','No account connected'))}</p></div>${pill(p.connected?L('Compte identifié','Account identified'):p.configured?L('Prêt à autoriser','Ready for consent'):L('Configuration requise','Configuration required'),p.connected?'good':'')}</div><p class="fine">${p.id==='google'?'Gmail · Google Calendar · Google Tasks · Google Drive':'Outlook · Outlook Calendar · Microsoft To Do · OneDrive'}</p>${!p.configured?`<div class="banner warn">${L('L’éditeur doit renseigner le client OAuth de cette application dans le fichier .env. Les identifiants ChatGPT ne sont pas réutilisables ici.','The application developer must configure its OAuth client in .env. ChatGPT credentials cannot be reused here.')}</div>`:''}${p.id==='google'?`<p class="fine">${p.clientType==='desktop'?L('Client OAuth : Application de bureau. Retour de connexion local sur 127.0.0.1 ; l’interface revient ensuite à son adresse initiale.','OAuth client: Desktop app. Sign-in returns through local 127.0.0.1, then restores the original UI address.'):L('Client OAuth : Application Web. Pour un client Google de bureau, définir GOOGLE_OAUTH_CLIENT_TYPE=desktop dans .env et redémarrer.','OAuth client: Web application. For a Google Desktop client, set GOOGLE_OAUTH_CLIENT_TYPE=desktop in .env and restart.')}</p>`:''}${p.connected?serviceSummary(p):''}<form data-form="connect" data-provider="${p.id}"><fieldset><legend>${L('Lire uniquement les outils choisis','Read only the tools you choose')}</legend>${['mail','calendar','tasks','files'].map(f=>`<label class="check"><input type="checkbox" name="features" value="${f}" ${caps[f]||(!p.connected&&['mail','calendar'].includes(f))?'checked':''}>${escape(feat(f))}</label>`).join('')}</fieldset><fieldset><legend>${L('Écriture facultative, toujours après approbation','Optional writes, always after approval')}</legend>${['drafts','calendar_write','tasks_write'].map(f=>`<label class="check"><input type="checkbox" name="features" value="${f}" ${caps[f]?'checked':''}>${escape(feat(f))}</label>`).join('')}</fieldset><div class="actions"><button class="btn primary" type="submit" ${!p.configured?'disabled':''}>${p.connected?L('Réautoriser / étendre les droits','Reauthorize / extend permissions'):L('Connecter mon compte','Connect my account')}</button>${p.connected?button(L('Synchroniser','Sync'),'sync',{provider:p.id}):''}${p.connected?button(L('Déconnecter','Disconnect'),'disconnect',{provider:p.id},'danger'):''}</div></form><p class="fine">${L('Décocher un droit déjà accordé ne le révoque pas. Retirez l’accès à l’application chez le fournisseur pour réduire les droits.','Unchecking an already granted permission does not revoke it. Remove app access at the provider to reduce permissions.')}</p>${p.id==='google'?`<p class="fine">${L('Gmail accorde au droit « compose » la gestion et l’envoi de brouillons. Essentiel n’implémente aucune route d’envoi.','Gmail’s “compose” scope permits draft management and sending. Essentiel implements no send route.')}</p>`:`<p class="fine">${L('Mail.ReadWrite est demandé pour les brouillons. Mail.Send n’est jamais demandé.','Mail.ReadWrite is requested for drafts. Mail.Send is never requested.')}</p>`}${s?`<div class="time">${L('Dernière tentative : ','Last attempt: ')}${escape(fmt(s.lastSync))}</div>${(s.calendars?.length||s.lists?.length)?`<details><summary>${L('Choisir les calendriers et la liste de tâches','Choose calendars and task list')}</summary><form data-form="selection" data-provider="${p.id}">${s.calendars?.length?`<fieldset><legend>${L('Calendriers à croiser (10 maximum)','Calendars to cross-check (up to 10)')}</legend>${s.calendars.map(c=>`<label class="check"><input type="checkbox" name="calendars" value="${escape(c.id)}" ${(data.selections[p.id]?.calendarIds?.length?data.selections[p.id].calendarIds.includes(c.id):(c.primary||(!s.calendars.some(x=>x.primary)&&s.calendars[0].id===c.id)))?'checked':''}>${escape(c.title)}${c.canEdit?'':L(' · lecture seule',' · read only')}</label>`).join('')}</fieldset>`:''}${s.lists?.length?select('list',L('Liste de tâches affichée','Displayed task list'),s.lists.map(l=>[l.id,l.title]),data.selections[p.id]?.listId||s.selectedList?.id||s.lists[0].id):''}<p class="fine">${L('Une sélection de calendriers vide utilise le calendrier principal.','An empty calendar selection uses the primary calendar.')}</p><button class="btn" type="submit">${L('Enregistrer et synchroniser','Save and sync')}</button></form></details>`:''}`:''}<details><summary>${L('Permissions techniques exactes','Exact technical scopes')}</summary><pre class="code">${escape(p.scopes.join('\n')||L('Aucune permission accordée.','No permission granted.'))}</pre></details></section>`;});
  return heading(L('Vos comptes. Vos permissions.','Your accounts. Your permissions.'),L('Un compte Google et un compte Microsoft dans cette version. Les connexions sont réalisées par cette application avec votre consentement, pas par vos plugins ChatGPT.','One Google account and one Microsoft account in this version. Connections are made by this application with your consent, not through your ChatGPT plugins.'))+`<div class="banner">${L('Les données lues restent sur ce serveur local. Un appel à TypeSafe exige un consentement distinct, avec aperçu du texte transmis. Les fichiers ne sont pas envoyés au modèle.','Read data stays on this local server. A TypeSafe call requires separate consent and a preview of the transmitted text. Files are not sent to the model.')}</div><div class="cards">${cards.join('')}</div><div class="spacer"></div><section class="card"><h2>${L('Fonctionnement local','Local operation')}</h2><div class="spacer"></div><label class="check"><input type="checkbox" id="auto-sync" ${ui.automatic?'checked':''}>${L('Actualiser les comptes toutes les cinq minutes tant que cette page reste ouverte et inactive.','Refresh accounts every five minutes while this page remains open and idle.')}</label><p class="fine">${L('Aucune écriture ni analyse Jev automatique. Fermer la page arrête cette actualisation. Les services peuvent limiter les requêtes.','No automatic writes or Jev analysis. Closing the page stops these refreshes. Services may rate-limit requests.')}</p><div class="actions">${button(data.vault.persistent?L('Verrouiller le coffre','Lock vault'):L('Activer la conservation chiffrée','Enable encrypted persistence'),'vault')}${button(L('Effacer les données connectées','Erase connected data'),'erase',{},'danger')}<a class="btn" href="${embedded?'#lab':'/workspace?lang='+lang+'#lab'}">${L('Ouvrir le laboratoire System One','Open the System One lab')}</a></div><p class="fine">${L('L’effacement local ne supprime pas les objets créés dans vos outils et ne révoque pas les autorisations OAuth chez le fournisseur. Les données personnelles locales sont gérées dans Préférences et données ; elles ne sont pas synchronisées automatiquement avec les comptes.','Local erasure does not delete objects created in your tools or revoke provider OAuth grants. Personal local data is managed in Preferences and data; it is not automatically synchronized with accounts.')}</p></section>`;
}
function messageDialog(m){ui.message=m;const triage=ui.triage?.id===m.provider+':'+m.id?ui.triage.record:null,summary=ui.summary?.id===m.provider+':'+m.id?ui.summary:null;show(m.title||L('Message','Message'),`<div class="actions">${pill(P(m.provider))}${pill(m.full?L('Contenu chargé','Content loaded'):L('Aperçu','Preview'))}${m.truncated?pill(L('Texte tronqué à 8 000 caractères','Text truncated to 8,000 characters'),'warn'):''}</div><dl class="kv"><dt>${L('De','From')}</dt><dd>${escape(m.from)}</dd><dt>${L('Reçu le','Received')}</dt><dd>${escape(fmt(m.receivedAt))}</dd><dt>${L('Relu le','Read at')}</dt><dd>${escape(fmt(m.observedAt))}</dd></dl><div class="source">${escape(m.text||L('Aucun texte exploitable. Ouvrez le message original ; les pièces jointes ne sont pas analysées.','No usable text. Open the original message; attachments are not analyzed.'))}</div><p class="fine">${L('Un message isolé, pas tout le fil de conversation. Les pièces jointes et le contenu distant ne sont pas chargés.','One message, not the whole conversation thread. Attachments and remote content are not loaded.')}</p>${triage?`<div class="banner"><strong>${L('Avis Jev, à vérifier : ','Jev assessment, review it: ')}</strong>${escape(triage.action||triage.bucket)}${triage.suggestedDate?' · '+escape(triage.suggestedDate):''}</div>${triage.evidence?`<blockquote class="block-source">${escape(triage.evidence)}</blockquote>`:''}<details><summary>${L('Voir les réponses structurées','View structured answers')}</summary><pre class="code">${escape(JSON.stringify({model:triage.model,answers:triage.answers,flags:triage.flags,reason:triage.reason},null,2))}</pre></details>`:''}${summary?`<div class="banner"><strong>${escape(L('Résumé rédigé par ','Summary written by ')+engineLabel(summary))}${L(', à vérifier : ',', review it: ')}</strong>${escape(summary.text)}</div>${summary.notes?.length?`<ul class="fine">${summary.notes.map(n=>`<li>${escape(n)}</li>`).join('')}</ul>`:''}`:''}<div class="actions">${button(L('Préparer un brouillon','Prepare a draft'),'compose-source',{kind:'draft'},'primary',!connected().some(p=>p.capabilities.drafts))}${button(L('Créer une tâche liée','Create linked task'),'compose-source',{kind:'task'},'',!connected().some(p=>p.capabilities.tasks_write))}${button(L('Réserver du temps','Reserve time'),'compose-source',{kind:'event'},'',!connected().some(p=>p.capabilities.calendar_write))}${link(m.url,L('Ouvrir l’original','Open original'),'btn')}${button(L('Évaluer avec Jev','Assess with Jev'),'triage',{},'',!config.configured||!m.text)}${button(L('Proposer une réponse avec ','Suggest a reply with ')+engineName(),'llm-draft',{kind:'reply'},'',!draftReady()||!m.text)}${button(L('Résumer avec ','Summarize with ')+engineName(),'llm-draft',{kind:'summary'},'',!draftReady()||!m.text)}</div><p class="fine">${draftReady()?L('Jev juge (choix, probabilités, confiance) ; le moteur de rédaction écrit un texte à relire. Aucun des deux n’envoie ni ne crée quoi que ce soit.','Jev judges (choice, probabilities, confidence); the drafting engine writes text for review. Neither sends nor creates anything.'):L('Rédaction assistée désactivée : définir DRAFT_ENGINE dans .env (API, LLM local, Claude Code ou Codex ; voir docs/LLM-DRAFTING.md) puis redémarrer.','Assisted drafting is off: set DRAFT_ENGINE in .env (API, local LLM, Claude Code or Codex; see docs/LLM-DRAFTING.md), then restart.')}</p><p class="fine">${L('Les boutons d’écriture nécessitent les droits correspondants dans Connexions. Aucun message n’est envoyé par cette version : le brouillon est à relire et envoyer dans votre messagerie.','Write buttons require corresponding permissions in Connections. This version sends no messages: review and send the draft in your mail application.')}</p>`);}
function composer(actionKind,source=null,payload={},preferred='',generated=null){
  const feature={draft:'drafts',event:'calendar_write',task:'tasks_write'}[actionKind],choices=connected().filter(p=>p.capabilities[feature]);
  if(!choices.length)throw new Error(L('Autorisez cette écriture dans Connexions.','Authorize this write in Connections.'));
  const p=choices.find(x=>x.id===(preferred||source?.provider))||choices[0],s=data.snapshots[p.id]||{};
  ui.compose={kind:actionKind,source,payload,provider:p.id,generated};
  const name=actionKind==='draft'?L('Réponse à relire','Reply for review'):kind(actionKind);
  const accountPicker=select('provider',L('Compte de destination','Destination account'),choices.map(x=>[x.id,P(x.id)+' · '+x.email]),p.id);
  let fields='';
  if(actionKind==='draft')fields=input('to',L('Destinataire exact','Exact recipient'),payload.to??source?.replyTo??'','email','required maxlength="254"')+input('subject',L('Objet','Subject'),payload.subject??(source?.title?'Re: '+source.title:''),'text','required maxlength="200"')+textarea('body',L('Réponse à enregistrer comme brouillon','Reply to save as draft'),payload.body??'','required maxlength="12000" rows="8"')+(generated?`<div class="banner warn"><strong>${escape(L('Brouillon rédigé par ','Draft written by ')+engineLabel(generated))}</strong> — ${L('à relire ; rien n’est envoyé ni créé sans votre approbation.','review it; nothing is sent or created without your approval.')}${generated.notes?.length?`<ul>${generated.notes.map(n=>`<li>${escape(n)}</li>`).join('')}</ul>`:''}</div>`:'')+`<div class="actions">${button(L('Modèle : bien reçu','Template: received'),'reply-template',{template:'received'},'small')}${button(L('Modèle : demande de précision','Template: clarification'),'reply-template',{template:'clarify'},'small')}${source?.text?button(L('Proposer le texte avec ','Suggest text with ')+engineName(),'llm-draft',{kind:'reply'},'small',!draftReady()):''}</div><p class="fine">${L('Les modèles sont des textes fixes et modifiables, pas des réponses écrites par Jev. Une nouvelle ébauche est créée ; le rattachement au fil Outlook n’est pas garanti.','Templates are fixed, editable text, not replies written by Jev. A new draft is created; Outlook conversation threading is not guaranteed.')}</p>`;
  if(actionKind==='task'){const lists=s.lists||[];fields=select('listId',L('Liste de destination','Destination list'),lists.map(l=>[l.id,l.title]),payload.listId||s.selectedList?.id||lists[0]?.id,'required')+input('title',L('Action à réaliser','Action to perform'),payload.title??source?.title??'','text','required maxlength="200"')+input('due',L('Date choisie et confirmée (facultative)','Chosen, confirmed date (optional)'),payload.due||'','date','min="2000-01-01" max="2099-12-31"')+textarea('notes',L('Notes transmises à l’outil','Notes sent to the tool'),payload.notes??(source?.url?'Source: '+source.url:''),'maxlength="6000"')+`<p class="fine">${L('Aucune échéance n’est déduite automatiquement du message. Une date seule est transmise ; l’API Google Tasks ne conserve pas une heure d’échéance.','No deadline is inferred automatically from the message. A date only is transmitted; the Google Tasks API does not retain a due time.')}</p>`;}
  if(actionKind==='event'){const calendars=(s.calendars||[]).filter(c=>c.canEdit);const start=payload.start||tomorrow().toISOString(),end=payload.end||new Date(Date.parse(start)+1800000).toISOString();fields=select('calendarId',L('Calendrier de destination','Destination calendar'),calendars.map(c=>[c.id,c.title]),payload.calendarId||calendars.find(c=>c.primary)?.id||calendars[0]?.id,'required')+input('title',L('Titre du créneau','Time-block title'),payload.title??source?.title??'','text','required maxlength="200"')+`<div class="two">${input('start',L('Début · heure locale du navigateur','Start · browser local time'),localInput(start),'datetime-local','required')}${input('end',L('Fin · heure locale du navigateur','End · browser local time'),localInput(end),'datetime-local','required')}</div>`+textarea('notes',L('Notes transmises au calendrier','Notes sent to the calendar'),payload.notes??(source?.url?'Source: '+source.url:''),'maxlength="6000"')+`<div class="banner warn">${L('Créneau privé, sans participant ni invitation. Aucun rendez-vous externe n’est confirmé. Aucun rappel n’est activé par cette application. Le calendrier peut rester visible aux personnes déjà autorisées dans votre compte.','Private time block, without attendees or invitations. No external appointment is confirmed. This application enables no reminder. The calendar may remain visible to people already authorized in your account.')}</div>`;}
  show(name,`<form data-form="compose" data-kind="${actionKind}">${accountPicker}${source?`<div class="block-source">${L('Source liée : ','Linked source: ')}${escape(P(source.provider)+' · '+source.title)}${source.provider!==p.id?`<br>${L('Attention : transfert de contenu entre deux comptes. Vérifiez les données incluses.','Attention: content is crossing accounts. Review the included data.')}`:''}</div>`:''}<div id="composeFields">${fields}</div>${footer(L('Voir l’aperçu exact','Review exact preview'))}</form>`);
}
function previewDialog(a){show(L('Approuver cette opération exacte','Approve this exact operation'),`<div class="actions">${pill(P(a.provider))}${pill(kind(a.kind))}</div><dl class="kv"><dt>${L('Compte','Account')}</dt><dd>${escape(a.account)}</dd>${Object.entries(a.payload).filter(([k])=>!['version','taskId','listId','calendarId'].includes(k)).map(([k,v])=>`<dt>${escape(({to:L('Destinataire','Recipient'),subject:L('Objet','Subject'),body:L('Texte','Body'),title:L('Titre','Title'),notes:L('Notes','Notes'),due:L('Date','Date'),calendarName:L('Calendrier','Calendar'),listName:L('Liste','List'),start:L('Début','Start'),end:L('Fin','End')})[k]||k)}</dt><dd>${escape(['start','end'].includes(k)?fmt(v):v||'—')}</dd>`).join('')}</dl>${a.source?`<div class="block-source">${L('Source : ','Source: ')}${escape(a.source.title)}<br>${link(a.source.url,L('Voir la source','Open source'),'')}${a.source.provider!==a.provider?`<p>${L('Des informations de cette source seront transmises à un autre compte.','Information from this source will be sent to another account.')}</p>`:''}</div>`:''}<div class="banner warn">${a.kind==='draft'?L('Cette opération crée un vrai brouillon dans votre messagerie. Elle ne l’envoie pas.','This creates a real draft in your mailbox. It does not send it.'):a.kind==='event'?L('Cette opération crée un vrai créneau personnel. Les calendriers sélectionnés seront relus avant la création. Aucune invitation ne sera envoyée.','This creates a real personal time block. Selected calendars will be read again before creation. No invitation will be sent.'):L('Cette opération modifie votre outil de tâches réel. Une création ne signifie pas que le travail est terminé.','This changes your real task tool. Creating a task does not mean the work is completed.')}</div><form data-form="approve" data-id="${escape(a.id)}" data-hash="${escape(a.approvalHash)}"><label class="check"><input type="checkbox" name="approved" required>${L('J’ai vérifié le compte, le contenu et les dates. J’autorise cette opération.','I checked the account, content and dates. I authorize this operation.')}</label><p class="fine">${L('Aperçu valable jusqu’à ','Preview valid until ')}${escape(fmt(a.expiresAt))}</p><div class="dialog-footer">${button(L('Annuler la proposition','Cancel proposal'),'cancel-action',{id:a.id})}<button class="btn primary" type="submit">${L('Exécuter dans mon outil','Execute in my tool')}</button></div></form>`);}
function actionDetails(a){show(kind(a.kind),`<div class="actions">${pill(state(a.status),a.status==='verified'?'good':['uncertain','created_unverified'].includes(a.status)?'warn':'')}</div>${a.diagnostic?diagnosticCard(a.provider,{service:a.diagnostic.service,diagnostic:a.diagnostic},true):''}${a.error?`<div class="spacer"></div><div class="banner warn">${escape(a.error)}</div>`:''}<dl class="kv"><dt>${L('Compte','Account')}</dt><dd>${escape(a.account)}</dd><dt>${L('Opération','Operation')}</dt><dd>${escape(a.id)}</dd><dt>${L('Approbation humaine','Human approval')}</dt><dd>${escape(fmt(a.approvedAt))}</dd><dt>${L('Objet fournisseur','Provider object')}</dt><dd>${escape(a.receipt?.id||'—')}</dd><dt>${L('Relecture réussie','Successful read-back')}</dt><dd>${escape(fmt(a.receipt?.verifiedAt))}</dd></dl><div class="actions">${a.receipt?.url?link(a.receipt.url,L('Vérifier dans le service','Check in service'),'btn'):''}${a.receipt?.id?button(L('Relire la preuve','Read back again'),'verify-action',{id:a.id}):''}${a.status==='pending'?button(L('Revoir la proposition','Review proposal'),'review-action',{id:a.id},'primary'):''}</div><details><summary>${L('Détail technique exportable','Exportable technical details')}</summary><pre class="code">${escape(JSON.stringify(a,null,2))}</pre></details><p class="fine">${L('La relecture confirme l’objet identifié. Elle ne confirme ni la livraison d’un message, ni l’accord d’un tiers, ni un bénéfice financier.','Read-back confirms the identified object. It does not confirm message delivery, third-party agreement or financial benefit.')}</p>`);}
function slotForm(){const d=new Date();d.setHours(9,0,0,0);if(+d<Date.now())d.setDate(d.getDate()+1);const end=new Date(d);end.setHours(18);show(L('Chercher un créneau dans mes calendriers','Find a slot in my calendars'),`<form data-form="slots"><div class="two">${input('from',L('À partir du','From'),localInput(d),'datetime-local','required')}${input('to',L('Jusqu’au','Until'),localInput(end),'datetime-local','required')}</div>${input('minutes',L('Durée en minutes','Duration in minutes'),30,'number','min="5" max="480" required')}<p class="fine">${L('Lecture à jour de tous les calendriers sélectionnés et autorisés. Fenêtre de sept jours maximum. Une erreur ou une pagination incomplète bloque le résultat plutôt que d’inventer une disponibilité.','Fresh read of all selected, authorized calendars. Up to seven days. An error or incomplete pagination blocks the result rather than inventing availability.')}</p>${footer(L('Lire mes calendriers et calculer','Read my calendars and calculate'))}</form>`);}
function slotsDialog(result){
  ui.slots=result;
  const entries=result.slots.length?result.slots.map((s,i)=>`<div class="row"><div class="row-main"><h3>${escape(fmt(s.start))} — ${escape(fmt(s.end))}</h3><p>${L('Aucun conflit dans les calendriers vérifiés.','No conflict in the checked calendars.')}</p>${button(L('Préparer ce créneau','Prepare this time block'),'use-slot',{index:i},'small',!connected().some(p=>p.capabilities.calendar_write))}</div></div>`).join(''):`<p>${L('Aucun créneau de cette durée trouvé dans cette fenêtre.','No slot of this duration found in this window.')}</p>`;
  show(L('Créneaux libres dans le périmètre vérifié','Free slots within the checked scope'),`<p class="fine">${L('Vérifié le ','Checked at ')}${escape(fmt(result.checkedAt))}. ${L('Calendriers : ','Calendars: ')}${escape(result.coverage.map(c=>P(c.provider)+' / '+c.title).join(' · '))}</p>${entries}<p class="fine">${L('Une proposition par intervalle libre. Ce n’est pas une réservation ; une nouvelle lecture précède l’écriture.','One proposal per free interval. This is not a reservation; a fresh read precedes the write.')}</p>`);
}
function vaultDialog(){if(data.vault.persistent&&!data.vault.locked)return work(async()=>{await api('vault',{action:'lock'});clearSensitive();await reload();});show(data.vault.locked?L('Déverrouiller le coffre local','Unlock local vault'):L('Conserver mes connexions chiffrées','Keep my connections encrypted'),`<form data-form="vault">${input('password',L('Phrase secrète locale · 12 caractères minimum','Local passphrase · at least 12 characters'),'','password','required minlength="12" maxlength="256" autocomplete="off"')}${!data.vault.exists?input('confirm',L('Confirmer la phrase secrète','Confirm passphrase'),'','password','required minlength="12" maxlength="256" autocomplete="off"'):''}<p class="fine">${L('Chiffrement AES-256-GCM avec clé dérivée par scrypt. La phrase secrète n’est jamais enregistrée. Sans elle, les connexions conservées ne sont pas récupérables. Le fichier chiffré est local, pas infonuagique.','AES-256-GCM encryption with a scrypt-derived key. The passphrase is never saved. Without it, saved connections cannot be recovered. The encrypted file is local, not cloud storage.')}</p>${footer(L('Déverrouiller et conserver chiffré','Unlock and keep encrypted'))}</form>`);}
function clearSensitive(){ui.message=null;ui.triage=null;ui.summary=null;ui.draftSource=null;ui.draftCompose=null;ui.files=null;ui.slots=null;ui.compose=null;ui.automatic=false;$('dialog').close();$('dialogBody').innerHTML='';}
function getAction(id){const a=data.actions.find(x=>x.id===id);if(!a)throw new Error(L('Action introuvable.','Action not found.'));return a;}
async function syncAll(){for(const p of connected())await api('sync',{provider:p.id});await reload();toast(L('Lecture terminée. Les erreurs éventuelles restent visibles par service.','Read complete. Any errors remain visible by service.'));}
$('dialog').addEventListener('cancel',e=>{if(ui.busy)e.preventDefault();});
window.addEventListener('hashchange',()=>{if(embedded)return;ui.route=location.hash.slice(1)||'inbox';render();});
document.addEventListener('click',e=>{
  if(!ownsEvent(e))return;
  const node=e.target.closest('[data-action]');if(!node||ui.busy)return;const a=node.dataset.action;
  if(a==='close'){$('dialog').close();return;}
  if(a==='language'){$('notice').hidden=true;lang=lang==='fr'?'en':'fr';try{sessionStorage.setItem('essentiel-connected-language',lang);}catch{}render();return;}
  if(a==='theme'){ui.theme=ui.theme==='light'?'dark':'light';render();return;}
  if(a==='vault'){vaultDialog();return;}
  if(a==='compose'){composer(node.dataset.kind);return;}
  if(a==='compose-source'){composer(node.dataset.kind,ui.message);return;}
  if(a==='slot-form'){slotForm();return;}
  if(a==='use-slot'){const slot=ui.slots.slots[Number(node.dataset.index)];composer('event',null,{start:slot.start,end:slot.end});return;}
  if(a==='reply-template'){const target=$('dialog').querySelector('textarea[name=body]');if(target)target.value=node.dataset.template==='received'?L('Bonjour,\n\nMerci pour votre message. Je l’ai bien reçu.\n\nCordialement,','Hello,\n\nThank you for your message. I have received it.\n\nRegards,'):L('Bonjour,\n\nPourriez-vous préciser votre demande ainsi que l’échéance attendue ?\n\nMerci.','Hello,\n\nCould you clarify your request and the expected deadline?\n\nThank you.');return;}
  if(a==='review-action'){previewDialog(getAction(node.dataset.id));return;}
  if(a==='action-details'){actionDetails(getAction(node.dataset.id));return;}
  if(a==='erase'){show(L('Effacer les données connectées locales','Erase local connected data'),`<form data-form="erase"><div class="banner warn">${L('Les jetons, sources et journaux connectés seront supprimés de ce serveur. Les objets déjà créés dans Google ou Microsoft resteront en place. Les droits OAuth devront être révoqués chez le fournisseur.','Connected tokens, sources and journals will be removed from this server. Objects already created in Google or Microsoft will remain. OAuth grants must be revoked at the provider.')}</div>${input('confirmation',L('Saisir ERASE pour confirmer','Type ERASE to confirm'),'','text','required pattern="ERASE" autocomplete="off"')}${footer(L('Effacer localement','Erase locally'))}</form>`);return;}
  if(a==='disconnect'){show(L('Déconnecter ce compte localement','Disconnect this account locally'),`<form data-form="disconnect" data-provider="${node.dataset.provider}"><p>${L('Les jetons et les données connectées de ce compte seront retirés du coffre. Les actions créées dans les outils resteront en place.','Tokens and connected data for this account will be removed from the vault. Actions created in the tools will remain.')}</p><p class="fine">${L('Cette opération ne révoque pas le consentement OAuth chez Google ou Microsoft. Retirez aussi l’accès dans les paramètres du fournisseur pour une révocation complète.','This does not revoke Google or Microsoft OAuth consent. Remove app access in the provider’s settings for full revocation.')}</p>${footer(L('Déconnecter localement','Disconnect locally'))}</form>`);return;}
  if(a==='llm-draft'){
    const form=$('dialog').querySelector('form[data-form="compose"]'),m=form?ui.compose.source:ui.message,kindV=node.dataset.kind==='summary'?'summary':'reply';
    if(!m?.text)return;ui.draftSource=m;ui.draftCompose=null;
    if(form){const fields=Object.fromEntries(new FormData(form)),preferred=fields.provider;delete fields.provider;ui.draftCompose={payload:fields,preferred};}
    const where=config.draft?.local?L('Moteur local : le texte reste sur cet ordinateur.','Local engine: the text stays on this computer.'):['claude','codex'].includes(config.draft?.engine)?L('Le CLI s’exécute avec votre propre compte, sans outils, dans un dossier temporaire vide ; le texte est transmis à son fournisseur.','The CLI runs with your own account, without tools, in an empty temporary folder; the text goes to its provider.'):L('Le texte quitte cet ordinateur vers le fournisseur configuré ; ses conditions et frais s’appliquent.','The text leaves this computer for the configured provider; its terms and charges apply.');
    show(L('Aperçu du texte envoyé à ','Preview text sent to ')+engineName(),`<form data-form="llm-draft" data-kind="${kindV}">${textarea('text',L('Texte transmis · retirer les données inutiles','Transmitted text · remove unnecessary data'),m.text,'required maxlength="8000" rows="10"')}${input('instructions',L('Consigne facultative (ton, points à couvrir)','Optional instruction (tone, points to cover)'),'','text','maxlength="500"')}<label class="check"><input type="checkbox" name="consent" required>${escape(L('J’autorise l’envoi de cet extrait à ','I authorize sending this excerpt to ')+engineLabel()+L(' pour obtenir un texte à relire.',' to get text for review.'))}</label><p class="fine">${where} ${L('Le moteur écrit un texte modifiable ; il ne juge pas, n’envoie rien et ne crée rien. Jev reste le seul juge typé.','The engine writes editable text; it does not judge, send or create anything. Jev remains the only typed judge.')}</p>${footer(L('Envoyer uniquement ce texte','Send only this text'))}</form>`);return;
  }
  if(a==='triage'){
    const m=ui.message;show(L('Aperçu du texte envoyé à TypeSafe','Preview text sent to TypeSafe'),`<form data-form="triage">${textarea('text',L('Texte transmis · retirer les données inutiles','Transmitted text · remove unnecessary data'),m.text,'required maxlength="8000" rows="12"')}<label class="check"><input type="checkbox" name="consent" required>${L('J’autorise l’envoi de cet extrait à TypeSafe pour obtenir des jugements structurés.','I authorize sending this excerpt to TypeSafe for structured judgments.')}</label><p class="fine">${L('Jev classe et sélectionne. Il ne rédige pas la réponse et ne déclenche aucune action externe. Les frais et conditions du fournisseur s’appliquent.','Jev classifies and selects. It does not write a reply or trigger any external action. Provider charges and terms apply.')}</p>${footer(L('Envoyer uniquement ce texte','Send only this text'))}</form>`);return;
  }
  if(a==='export'){
    show(L('Exporter le journal en texte non chiffré','Export the journal as unencrypted text'),`<form data-form="export"><p>${L('Le fichier JSON contient les contenus approuvés, adresses, références sources et reçus. Il ne contient pas les jetons OAuth. Protégez ce fichier comme vos données personnelles.','The JSON file contains approved contents, addresses, source references and receipts. It contains no OAuth tokens. Protect this file as personal data.')}</p>${footer(L('Exporter le JSON','Export JSON'))}</form>`);return;
  }
  work(async()=>{
    if(a==='diagnostics'){await api('diagnostics',{provider:node.dataset.provider});await reload();toast(L('Tests de lecture terminés. Consultez les résultats dans Connexions.','Read checks completed. Inspect their results in Connections.'));location.hash=href('connections');}
    if(a==='export-diagnostic'){
      const report=data.diagnostics?.[node.dataset.provider];if(!report)return;
      const safe={app:'Essentiel',version:'0.3.2',...report};
      const url=URL.createObjectURL(new Blob([JSON.stringify(safe,null,2)],{type:'application/json'}));
      const a=document.createElement('a');a.href=url;a.download='essentiel-access-diagnostic.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
    }
    if(a==='sync-all')await syncAll();
    if(a==='sync'){await api('sync',{provider:node.dataset.provider});await reload();}
    if(a==='message'){const m=await api('message',{provider:node.dataset.provider,id:node.dataset.id});await reload();messageDialog(m);}
    if(a==='complete-task'){const proposal=await api('actions/preview',{provider:node.dataset.provider,kind:'complete_task',payload:{taskId:node.dataset.id,listId:node.dataset.list}});await reload();previewDialog(proposal);}
    if(a==='cancel-action'){await api('actions/cancel',{id:node.dataset.id});$('dialog').close();await reload();}
    if(a==='verify-action'){const result=await api('actions/verify',{id:node.dataset.id});await reload();actionDetails(result);}
  });
});
document.addEventListener('change',e=>{
  if(!ownsEvent(e))return;
  if(e.target.id==='auto-sync'){ui.automatic=e.target.checked;return;}
  if(e.target.name==='provider'&&e.target.form?.dataset.form==='compose'&&!ui.busy){const fields=Object.fromEntries(new FormData(e.target.form)),saved={...fields};delete saved.provider;if(saved.start)saved.start=isoInput(saved.start);if(saved.end)saved.end=isoInput(saved.end);delete saved.calendarId;delete saved.listId;composer(ui.compose.kind,ui.compose.source,saved,fields.provider,ui.compose.generated);}
});
document.addEventListener('submit',e=>{
  if(!ownsEvent(e))return;
  const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(ui.busy||!form.reportValidity())return;
  const f=new FormData(form),v=Object.fromEntries(f),type=form.dataset.form;
  if(type==='inbox-filter'){ui.search=v.q||'';ui.onlyUnread=f.has('unread');render();return;}
  work(async()=>{
    if(type==='connect'){const auth=await api('oauth/start',{provider:form.dataset.provider,features:f.getAll('features')});location.assign(auth.url);return;}
    if(type==='selection'){const p=form.dataset.provider;await api('selection',{provider:p,calendarIds:f.getAll('calendars'),listId:v.list||''});await api('sync',{provider:p});await reload();return;}
    if(type==='file-search'){ui.files=await api('files',{provider:v.provider,query:v.query});render();return;}
    if(type==='slots'){slotsDialog(await api('slots',{from:isoInput(v.from),to:isoInput(v.to),minutes:Number(v.minutes)}));return;}
    if(type==='compose'){
      const payload={...v};delete payload.provider;if(payload.start)payload.start=isoInput(payload.start);if(payload.end)payload.end=isoInput(payload.end);
      const source=ui.compose.source?{provider:ui.compose.source.provider,id:ui.compose.source.id}:null;
      const proposal=await api('actions/preview',{provider:v.provider,kind:form.dataset.kind,payload,source});await reload();previewDialog(proposal);return;
    }
    if(type==='approve'){
      const a=await api('actions/execute',{id:form.dataset.id,approvalHash:form.dataset.hash,approved:f.has('approved')});await reload();actionDetails(a);
      if(a.status==='verified')toast(L('Opération relue dans le service. La preuve est enregistrée.','Operation read back from the service. The receipt is recorded.'));return;
    }
    if(type==='vault'){
      if(v.confirm!==undefined&&v.confirm!==v.password)throw new Error(L('Les phrases secrètes diffèrent.','Passphrases do not match.'));
      const password=v.password;form.reset();await api('vault',{action:'unlock',password});$('dialog').close();await reload();return;
    }
    if(type==='erase'){await api('vault',{action:'erase',confirm:v.confirmation});clearSensitive();await reload();return;}
    if(type==='disconnect'){await api('disconnect',{provider:form.dataset.provider});clearSensitive();await reload();return;}
    if(type==='llm-draft'){
      const m=ui.draftSource,kindV=form.dataset.kind,back=ui.draftCompose;if(!m)return;
      const result=await api('/api/draft',{consent:f.has('consent'),kind:kindV,lang,text:v.text,instructions:v.instructions||''},125000);
      const generated={engine:result.engine,model:result.model,notes:result.notes||[]};
      if(kindV==='summary'){ui.summary={id:m.provider+':'+m.id,...generated,text:result.draft};messageDialog(m);return;}
      if(connected().some(p=>p.capabilities.drafts)){composer('draft',m,{...(back?.payload||{}),body:result.draft},back?.preferred||'',generated);return;}
      show(L('Brouillon à relire','Draft for review'),`<div class="banner warn"><strong>${escape(L('Brouillon rédigé par ','Draft written by ')+engineLabel(generated))}</strong> — ${L('à relire. Autorisez « Créer des brouillons » dans Connexions pour l’enregistrer dans votre messagerie, ou copiez-le.','review it. Authorize “Create drafts” in Connections to save it in your mailbox, or copy it.')}</div>${textarea('generated',L('Texte proposé (modifiable)','Suggested text (editable)'),result.draft,'rows="10"')}${generated.notes.length?`<ul class="fine">${generated.notes.map(n=>`<li>${escape(n)}</li>`).join('')}</ul>`:''}`);return;
    }
    if(type==='triage'){
      const m=ui.message;const result=await api('/api/analyze',{consent:f.has('consent'),today:new Date().toLocaleDateString('en-CA'),goals:[],item:{title:m.title.slice(0,200)||'Message',source:P(m.provider),text:v.text}});
      if(result.record.mode==='error')throw new Error(result.record.error||result.record.reason||'Jev evaluation failed.');
      ui.triage={id:m.provider+':'+m.id,record:result.record};messageDialog(m);return;
    }
    if(type==='export'){
      const exportData={app:'Essentiel',version:'0.3.2',exportedAt:new Date().toISOString(),note:'Technical records, not signed attestations. OAuth tokens excluded.',actions:data.actions};
      const url=URL.createObjectURL(new Blob([JSON.stringify(exportData,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='essentiel-connected-receipts.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('dialog').close();return;
    }
  });
});
setInterval(()=>{if((!embedded||$('connectedHost'))&&ui.automatic&&!ui.busy&&!$('dialog').open&&!data.vault.locked&&connected().length&&document.visibilityState==='visible')work(syncAll);},300000);
async function initializeConnected(){
  try{
    await reload();config=await api('/api/config');const params=new URLSearchParams(location.search),success=params.get('connected'),failure=params.get('connection_error');
    if(failure){
      const hints={
        OAUTH_STATE_INVALID:L('Tentative expirée, déjà utilisée ou ouverte dans un autre navigateur. Recommencer depuis « Connecter mon compte », pas depuis l’ancienne URL de retour.','The attempt expired, was already used, or belongs to another browser. Start again with “Connect my account”, not the old callback URL.'),
        OAUTH_LAUNCH_INVALID:L('Le lien de lancement local a expiré ou a déjà été utilisé. Recommencer depuis « Connecter mon compte ».','The local launch link expired or was already used. Start again with “Connect my account”.'),
        OAUTH_DENIED:L('Google ou Microsoft n’a pas accordé la connexion. Vérifier le consentement et les règles du compte.','Google or Microsoft did not grant the connection. Check consent and account policies.'),
        CONNECTOR_NOT_CONFIGURED:L('Renseigner le client OAuth dans .env et redémarrer le serveur local.','Configure the OAuth client in .env and restart the local server.')
      };
      ui.lastError=L('Connexion non terminée : ','Connection not completed: ')+(hints[failure]||failure)+' ('+failure+')';
    }
    if(success||failure)history.replaceState(null,'',`/?lang=${lang}${location.hash}`);
    render();if(success&&connected().some(p=>p.id===success))await work(async()=>{await api('sync',{provider:success});await reload();});
  }catch(e){ui.lastError=L('Serveur local indisponible. ','Local server unavailable. ')+e.message;render();}

}
export function mountConnected(options={}){
  hostOptions=options;lang=options.language||lang;ui.theme=options.theme||ui.theme;ui.route=options.route||'inbox';
  render();startup??=initializeConnected();return startup;
}
export function hideConnected(){if(embedded){$('dialog').close();$('notice').hidden=true;}}
if(!embedded)startup=initializeConnected();
